-- Aponta cada documento para sua versão v1 (DEFERRABLE FK).
update knowledge_documents d set current_version_id = v.id
from knowledge_document_versions v
where v.document_id = d.id and d.current_version_id is null;

-- Validação pós-carga (esperado: sources=39, documents=66, versions=66, sem_versao=0):
select (select count(*) from knowledge_sources) as sources,
       (select count(*) from knowledge_documents) as documents,
       (select count(*) from knowledge_document_versions) as versions,
       (select count(*) from knowledge_documents d where d.current_version_id is null) as sem_versao;
